return {["scripts/actions/abilities/animated_flourish.lua"]={["Path"]="scripts/actions/abilities/animated_flourish.lua",["SHA256"]="cfb9e5358df31c24ab939eeafc0f9c99ed7c84612d158252537b73f893169119",["Text"]="-----------------------------------\n-- Ability: Animated Flourish\n-- Provokes the target. Requires at least one, but uses two Finishing Moves.\n-- Obtained: Dancer Level 20\n-- Finishing Moves Used: 1-2\n-- Recast Time: 00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkFlourishAbility(player, target, ability, false, 1)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dancer.useAnimatedFlourishAbility(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/apogee.lua"]={["Path"]="scripts/actions/abilities/apogee.lua",["SHA256"]="24b8af364d4e7b268c5c2874b602d8b6390bf75d0da6742bbab29465b273d31a",["Text"]="-----------------------------------\n-- Ability: Apogee\n-- Increases the MP Cost of the Next Blood Pact but makes its recast timer 0\n-- Obtained: Summoner Level 70\n-- Recast Time: 5 Minutes\n-- Duration: 1 Blood Pact or 60 seconds, whichever occurs first.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.APOGEE) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.APOGEE, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.APOGEE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/arcane_circle.lua"]={["Path"]="scripts/actions/abilities/arcane_circle.lua",["SHA256"]="b722300ee032ade7c01c6df0b78a1d8c639247797a50fa56adbf20c8a625fb32",["Text"]="-----------------------------------\n-- Ability: Arcane Circle\n-- Description: Grants resistance, defense, and attack against Arcana to party members within the area of effect.\n-- Obtained: Dark Knight Level 5\n-- Recast Time: 00:05:00\n-- Duration: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dark_knight.useArcaneCircle(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/arcane_crest.lua"]={["Path"]="scripts/actions/abilities/arcane_crest.lua",["SHA256"]="f0271957c825df11e2c7ec783ce842d64ab3e4b168fd3a08fa991a02ebdc355e",["Text"]="-----------------------------------\n-- Ability: Arcane Crest\n-- Description: Lowers accuracy, evasion, magic accuracy, magic evasion and TP gain for arcana.\n-- Obtained: Dark Knight Level 87\n-- Recast Time: 00:05:00\n-- Duration: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dark_knight.checkArcaneCrest(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.dark_knight.useArcaneCrest(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/aspir_samba.lua"]={["Path"]="scripts/actions/abilities/aspir_samba.lua",["SHA256"]="433910ebb267a546b0bff902f2cd6ee9fa9495543dd17ed7472a3ce0f4aad69c",["Text"]="-----------------------------------\n-- Ability: Aspir Samba\n-- Inflicts the next target you strike with Aspir daze, allowing all those engaged in battle with it to drain its MP.\n-- Obtained: Dancer Level 25\n-- TP Required: 10%\n-- Recast Time: 1:00\n-- Duration: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FAN_DANCE) then\n        return xi.msg.basic.UNABLE_TO_USE_JA2, 0\n    elseif player:hasStatusEffect(xi.effect.TRANCE) then\n        return 0, 0\n    elseif player:getTP() < 100 then\n        return xi.msg.basic.NOT_ENOUGH_TP, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    -- Only remove TP if the player doesn't have Trance.\n    if not player:hasStatusEffect(xi.effect.TRANCE) then\n        player:delTP(100)\n    end\n\n    local duration = 120 + player:getMod(xi.mod.SAMBA_DURATION) + (player:getJobPointLevel(xi.jp.SAMBA_DURATION) * 2)\n    duration       = duration * (100 + player:getMod(xi.mod.SAMBA_PDURATION)) / 100\n\n    player:delStatusEffect(xi.effect.HASTE_SAMBA)\n    player:delStatusEffect(xi.effect.DRAIN_SAMBA)\n    player:addStatusEffect(xi.effect.ASPIR_SAMBA, { power = 1, duration = duration, origin = player })\n\n    return xi.effect.ASPIR_SAMBA\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/aspir_samba_ii.lua"]={["Path"]="scripts/actions/abilities/aspir_samba_ii.lua",["SHA256"]="edf3b77574b360af6e787ed8bcab1ecf7c76ea115189e70db9b8bc8a11e7a5cb",["Text"]="-----------------------------------\n-- Ability: Aspir Samba II\n-- Inflicts the next target you strike with Aspir daze, allowing all those engaged in battle with it to drain its MP.\n-- Obtained: Dancer Level 60\n-- Recast Time: 1:00\n-- TP Cost: 25%\n-- Duration: 1:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FAN_DANCE) then\n        return xi.msg.basic.UNABLE_TO_USE_JA2, 0\n    elseif player:hasStatusEffect(xi.effect.TRANCE) then\n        return 0, 0\n    elseif player:getTP() < 250 then\n        return xi.msg.basic.NOT_ENOUGH_TP, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    -- Only remove TP if the player doesn't have Trance.\n    if not player:hasStatusEffect(xi.effect.TRANCE) then\n        player:delTP(250)\n    end\n\n    local duration = 120 + player:getMod(xi.mod.SAMBA_DURATION) + (player:getJobPointLevel(xi.jp.SAMBA_DURATION) * 2)\n    duration       = duration * (100 + player:getMod(xi.mod.SAMBA_PDURATION)) / 100\n\n    player:delStatusEffect(xi.effect.HASTE_SAMBA)\n    player:delStatusEffect(xi.effect.DRAIN_SAMBA)\n    player:addStatusEffect(xi.effect.ASPIR_SAMBA, { power = 2, duration = duration, origin = player })\n\n    return xi.effect.ASPIR_SAMBA\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/assassins_charge.lua"]={["Path"]="scripts/actions/abilities/assassins_charge.lua",["SHA256"]="6e7e4f89255d4f2e929d8e09b302991fb1678450a76e42d810504dbe1458bd7d",["Text"]="-----------------------------------\n-- Ability: Assassin's Charge\n-- Will triple your next attack.\n-- Obtained: Thief Level 75\n-- Recast Time: 5:00\n-- Duration: 1:00 minute\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.thief.useAssassinsCharge(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/assault.lua"]={["Path"]="scripts/actions/abilities/assault.lua",["SHA256"]="0bbd9bd64747b12492e3149579030d14774f82b0ec2711a7d1def7acec5ecb1b",["Text"]="-----------------------------------\n-- Ability: Assault\n-- Orders the avatar to attack.\n-- Obtained: Summoner Level 1\n-- Recast Time: 10 sec\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:petAttack(target)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/astral_conduit.lua"]={["Path"]="scripts/actions/abilities/astral_conduit.lua",["SHA256"]="e1ce5ab3a76c43ff0ecf52001f6c67f5d8505f08fa5bada7620baa6498e8c3e6",["Text"]="-----------------------------------\n-- Ability: Astral Conduit\n-- Description: Reduces Blood Pact recast times.\n-- Obtained: SMN Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.ASTRAL_CONDUIT, { power = 15, duration = 30, origin = player, tick = 1 })\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/astral_flow.lua"]={["Path"]="scripts/actions/abilities/astral_flow.lua",["SHA256"]="4d5c6a240d87b7c637aa8eed38569945f96318525484d4dd35eba8c4a9dda5ff",["Text"]="-----------------------------------\n-- Ability: Accession\n-- Allows avatars to use their full strength and allows summmoning of Odin and Alexander.\n-- Obtained: Summoner Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.ASTRAL_FLOW, { power = 1, duration = 180, origin = player })\n\n    return xi.effect.ASTRAL_FLOW\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/asylum.lua"]={["Path"]="scripts/actions/abilities/asylum.lua",["SHA256"]="52a019e436d78f94c5b46a60c13b340afffa61b87c9a7b808375c