ility, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/battuta.lua"]={["Path"]="scripts/actions/abilities/battuta.lua",["SHA256"]="76357ce3c014702ebd00343a4903044ac1ea5af09247ea9d04d62db491f5a07f",["Text"]="-----------------------------------\n-- Ability: Battuta\n-- Increases the likelihood of parrying and deals counter damage after parrying dependent upon harbored runes.\n-- Obtained: Rune Fencer Level 75 (merit)\n-- Recast Time: 5:00\n-- Duration: 1:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.rune_fencer.checkHaveRunes(player)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useBattuta(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/beast_roll.lua"]={["Path"]="scripts/actions/abilities/beast_roll.lua",["SHA256"]="8818506511d4752670df5e583a371837d95d9a72955495028e9b405dad00c750",["Text"]="-----------------------------------\n-- Ability: Beast Roll\n-- Enhances pet attacks for party members within area of effect\n-- Optimal Job: Beastmaster\n-- Lucky Number: 4\n-- Unlucky Number: 8\n-- Level: 34\n-- Phantom Roll +1 Value: 3\n--\n-- Die Roll |No BST     |With BST\n-- -------- --------    -----------\n-- 1        |16         |41\n-- 2        |20         |45\n-- 3        |24         |49\n-- 4        |64         |89\n-- 5        |28         |53\n-- 6        |32         |57\n-- 7        |40         |65\n-- 8        |8          |33\n-- 9        |44         |69\n-- 10       |48         |73\n-- 11       |80         |105\n-- Bust     |-25        |-25\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/benediction.lua"]={["Path"]="scripts/actions/abilities/benediction.lua",["SHA256"]="50291263bc54c1dec379afbc572341db96a211f12e58f53a530c20f04829b624",["Text"]="-----------------------------------\n-- Ability: Benediction\n-- Restores a large amount of HP and removes (almost) all status ailments for party members within area of effect.\n-- Obtained: White Mage Level 1\n-- Recast Time: 1:00:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.white_mage.checkBenediction(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.white_mage.useBenediction(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/berserk.lua"]={["Path"]="scripts/actions/abilities/berserk.lua",["SHA256"]="ff55ef2126ae9f1e5d12128c10a1df4d2f6ecbaebf4cc71b0e3d7dafac6329f8",["Text"]="-----------------------------------\n-- Ability: Berserk\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useBerserk(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/bestial_loyalty.lua"]={["Path"]="scripts/actions/abilities/bestial_loyalty.lua",["SHA256"]="bca01a19a0f531d838c5cfcc6b827943819167a2190e461d64d73e5388fa2418",["Text"]="-----------------------------------\n-- Ability: Bestial Loyalty\n-- Calls a beast to fight by your side without consuming bait\n-- Obtained: Beastmaster Level 23\n-- Recast Time: 20:00\n-- Duration: 