seAbility = function(player, target, ability)\n    xi.job_utils.geomancer.blazeOfGlory(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/blitzers_roll.lua"]={["Path"]="scripts/actions/abilities/blitzers_roll.lua",["SHA256"]="776e87f2ba150f532c2d2ab01f3c99e0891a596ab1e4e17ef0d25c7764872e9f",["Text"]="-----------------------------------\n-- Ability: Blitzer's Roll\n-- Reduces melee attack delay for party members within area of effect.\n-- Optimal Job: None\n-- Lucky Number: 4\n-- Unlucky Number: 9\n-- Level: 83\n-- Phantom Roll +1 Value: 1\n--\n-- Die Roll    | Delay Reduction %\n-- --------    -------\n-- 1           |+2\n-- 2           |+3\n-- 3           |+4\n-- 4           |+11\n-- 5           |+5\n-- 6           |+6\n-- 7           |+7\n-- 8           |+8\n-- 9           |+1\n-- 10          |+10\n-- 11          |+12\n-- Bust        |-5\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/blood_rage.lua"]={["Path"]="scripts/actions/abilities/blood_rage.lua",["SHA256"]="f6587992dad75e42b0b661c3446c8d6a5ae0ba3217b407b316b197644e08945f",["Text"]="-----------------------------------\n-- Ability: Blood Rage\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useBloodRage(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/blood_weapon.lua"]={["Path"]="scripts/actions/abilities/blood_weapon.lua",["SHA256"]="7efb6c046429e0ac40b847335b832d73899685bf81034bf5d177408e90166398",["Text"]="-----------------------------------\n-- Ability: Blood Weapon\n-- Description: Causes all attacks to drain enemy's HP.\n-- Obtained: Dark Knight Level 1\n-- Recast Time: 01:00:00\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dark_knight.checkBloodWeapon(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dark_knight.useBloodWeapon(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/bolster.lua"]={["Path"]="scripts/actions/abilities/bolster.lua",["SHA256"]="2b947bd8c679139f412641c4245553f6df20ab288cb97f3d37855d759d139c8c",["Text"]="-----------------------------------\n-- Ability: Bolster\n-- Enhances the effects of your geomancy spells.\n-- Doubles the potency of Geomancy spells while Bolster is active.\n-- Obtained: Geomancer Level 1\n-- Recast Time: 01:00:00\n-- Duration: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.geomancer.bolster(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/bolters_roll.lua"]={["Path"]="scripts/actions/abilities/bolters_roll.lua",["SHA256"]="7c622fcc2b7d47a52a8b5d2263683723195dd571688cd4e5e559bee6813ae410",["Text"]="-----------------------------------\n-- Ability: Bolter's Roll\n-- Increases Movement speed for party members with area of effect.\n-- Optimal Job: None\n-- Lucky Number: 3\n-- Unlucky Number: 9\n-- Level: 76\n-- Phantom Roll +1 Value: 4\n--\n-- Die Roll    | %\n-- --------    -------\n-- 1           |+6\n-- 2           |+6\n-- 3           |+16\n-- 4           |+8\n-- 5           |+8\n-- 6           |+10\n-- 7           |+10\n-- 8           |+12\n-- 9           |+4\n-- 10          |+14\n-- 11          |+20\n-- Bust        |0\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/boost.lua"]={["Path"]="scripts/actions/abilities/boost.lua",["SHA256"]="873dadc709fec71766c0b047213cf8e32f96f6bb9695b27fef3618ea15a3020d",["Text"]="-----------------------------------\n-- Ability: Boost\n-- Enhances user's next attack.\n-- Obtained: Monk Level 5\n-- Recast Time: 0:15\n-- Duration: 3:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useBoost(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/bounty_shot.lua"]={["Path"]="scripts/actions/abilities/bounty_shot.lua",["SHA256"]="d7159f69c73319ba66e8114f0913d75922647faab9fa21098aade36d288eb922",["Text"]="-----------------------------------\n-- Ability: Bounty Shot\n-- Description: Increases the rate at which the target yields treasure.\n-- Obtained: RNG Level 87\n-- Recast Time: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ranger.checkBountyShot(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useBountyShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/box_step.lua"]={["Path"]="scripts/actions/abilities/box_step.lua",["SHA256"]="8fcdcd68be5201f17990d12005bab24f4c99a28ed2a607053284a7117809352d",["Text"]="-----------------------------------\n-- Ability: Box Step\n-- Lowers target's defense. If successful, you will earn two Finishing Moves.\n-- Obtained: Dancer Level 30\n-- TP Required: 10%\n-- Recast Time: 00:05\n-- Duration: First Step lasts 1 minute, each following Step extends its current duration by 30 seconds.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkStepAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useStepAbility(player, target, ability, action, xi.effect.SLUGGISH_DAZE_1)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/brazen_rush.lua"]={["Path"]="scripts/actions/abilities/brazen_rush.lua",["SHA256"]="e1129e18bc1818a3a50fc03fa4de3f1fb91ba463448612abee09dd52e2d1d1de",["Text"]="-----------------------------------\n-- Ability: Brazen Rush\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.warrior.checkBrazenRush(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useBrazenRush(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/building_flourish.lua"]={["Path"]="scripts/actions/abilities/building_flourish.lua",["SHA256"]="da457cd014ff2a651b18463e95fffccdd0c726fea1ddab744ade3b2c45563a4f",["Text"]="-----------------------------------\n-- Ability: Building Flourish\n-- Enhances potency of your next weapon skill. Requires at least one Finishing Move.\n-- Obtained: Dancer Level 50\n-- Finishing Moves Used: 1-3\n-- Recast Time: 00:10\n-- Duration: 01:00\n--\n-- Using one Finishing Move boosts the Accuracy of your next weapon skill.\n-- Using two Finishing Moves boosts both the Accuracy and Attack of your next weapon skill.\n-- Using three Finishing Moves boosts the Accuracy, Attack and Critical Hit Rate of your next weapon skill.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkFlourishAbility(player, target, ability, false, 1)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dancer.useBuildingFlourishAbility(player, target, ability)\nend\n\nreturn abilityObject\n"}};
